const config = $('Config Empresa').first().json;
const row = $input.first().json;
const watermark = (row && row.last_synced_modified) ? row.last_synced_modified : '1970-01-01 00:00:00';
return [{ json: { ...config, watermark } }];

const config = $('Config Empresa').first().json;
const doc = $json.data; // Frappe envuelve el doc en { data: {...} }
const items = doc.items || [];
const dateKey = parseInt(doc.posting_date.replace(/-/g, ''), 10);
const taxTotal = doc.total_taxes_and_charges || 0;
const taxPerLine = items.length ? taxTotal / items.length : 0; // simplificado: prorrateo parejo entre líneas

return items.map(item => ({
  json: {
    company_id: config.company_id,
    date_key: dateKey,
    frappe_customer_name: doc.customer,
    frappe_item_code: item.item_code,
    frappe_doc_name: doc.name,
    frappe_doc_item_row: item.name,
    quantity: item.qty,
    uom: item.uom,
    unit_price: item.rate,
    discount_amount: item.discount_amount || 0,
    tax_amount: taxPerLine,
    total_amount: item.amount,
    cost_amount: (item.valuation_rate || 0) * item.qty,
    currency: doc.currency
  }
}));

