const config = $('Config Empresa').first().json;
const data = $json.data || [];
if (data.length === 0) {
  return [{ json: { skip: true } }];
}
const maxModified = data[data.length - 1].modified; // viene ordenado asc por 'modified'
return [{ json: { skip: false, company_id: config.company_id, frappe_doctype: config.frappe_doctype, max_modified: maxModified } }];
